#!/usr/bin/env python3
"""Kasten „Energie und Auto“ für den Steuerrechner (Entwurf, Faden Energie-Ersparnis).
Läuft auf jeder Fassung von steuerrechner/index.html, die die Anker unten hat; ein zweiter Lauf ändert nichts.
Aufruf: python3 werkzeug/energie-kasten.py [pfad/zu/steuerrechner/index.html]
Szenario-Regler: Der Fall steckt in <select id="e_fall"> mit den Werten ung / wahr / guen; nach dem Setzen updateHH() aufrufen."""
import sys
P = sys.argv[1] if len(sys.argv) > 1 else "steuerrechner/index.html"
s = open(P, encoding="utf-8").read()
if 'id="energieBox"' in s:
    print("schon drin, nichts zu tun"); sys.exit(0)
BOX = '        <details class="more" id="energieBox">\n          <summary>Energie und Auto: was Wärmepumpe, Solaranlage und E-Auto sparen</summary>\n          <p class="note" style="margin-top:0">Grobe Schätzung für ein Haus wie im Buch, heute und mit der Reform. Die Ersparnis zählt zum Geld im Portemonnaie. Kauf und Zinsen sind abgezogen, gerechnet als Mittel der nächsten 20 Jahre. Genauer rechnen die verknüpften Rechner.</p>\n          <div class="fields">\n            <div class="field"><label for="e_fall">Annahmen</label><select id="e_fall"><option value="ung">ungünstig</option><option value="wahr" selected>wahrscheinlich</option><option value="guen">günstig</option></select><span class="hint">für Preise, Technik und Zinsen</span></div>\n            <div class="field"><label for="e_strom">Haushaltsstrom im Jahr, kWh</label><input id="e_strom" type="number" min="0" step="100" value="3500"><span class="hint">ohne Wärmepumpe und Auto; leer lassen: nach Personen geschätzt</span></div>\n            <div class="field"><label for="e_wp">Heizung</label><select id="e_wp"><option value="0">bleibt wie sie ist</option><option value="1">Wärmepumpe statt Gas</option></select></div>\n            <div class="field"><label for="e_waerme">Wärme im Jahr, kWh</label><input id="e_waerme" type="number" min="0" step="500" value="15000"><span class="hint">ungefähr Gasverbrauch × 0,9</span></div>\n            <div class="field"><label for="e_ev">Auto</label><select id="e_ev"><option value="0">bleibt wie es ist</option><option value="1">E-Auto statt Verbrenner</option></select></div>\n            <div class="field"><label for="e_km">Kilometer im Jahr</label><input id="e_km" type="number" min="0" step="500" value="13500"></div>\n            <div class="field"><label for="e_pv">Solaranlage auf dem Dach, kWp</label><input id="e_pv" type="number" min="0" max="30" step="0.5" value="0"><span class="hint">0 = keine; mit Speicher, wenn er sich lohnt</span></div>\n            <label class="check field"><input id="e_balkon" type="checkbox"> Balkonkraftwerk 800 W</label>\n            <label class="check field wide"><input id="e_hhstrom" type="checkbox" checked> Auch den billigeren Strom für den eigenen Verbrauch einrechnen (Reform: 5 % Mehrwertsteuer, ohne Umlagen)</label>\n          </div>\n          <div id="e_quelle"></div>\n          <p class="note" id="e_links"></p>\n        </details>\n'
ERG = '        <div class="energie-erg" id="energieErg" hidden></div>\n'
JS = '\n/* ---------- Energie und Auto (Entwurf) ----------\n   Werte aus der Stundensimulation des Energie-Rechners (Einfamilienhaus, Idstein, 3.500 kWh, 15.000 kWh Wärme, 13.500 km),\n   Mittel 2027 bis 2046 mit Kauf und Zinsen. Var = Energieteil, wächst mit Wärme bzw. Kilometern; Fix = Kauf, Zinsen, Wartung, Steuer. */\nconst ENERGIE = {"ung_heute": {"hh": 0.3888, "wpVar": 363, "wpFix": -1034, "evVar": 942, "evFix": -723, "pv": 100, "synWp": 406, "synEv": 253, "synAll": -89, "balkon": 223, "alles": 219}, "ung_reform": {"hh": 0.2805, "wpVar": 1929, "wpFix": -422, "evVar": 2265, "evFix": -424, "pv": 117, "synWp": 314, "synEv": 129, "synAll": -21, "balkon": 157, "alles": 3887}, "wahr_heute": {"hh": 0.3695, "wpVar": 1039, "wpFix": -415, "evVar": 1471, "evFix": -372, "pv": 253, "synWp": 255, "synEv": 147, "synAll": 17, "balkon": 196, "alles": 2395}, "wahr_reform": {"hh": 0.2311, "wpVar": 2678, "wpFix": -115, "evVar": 2823, "evFix": -84, "pv": 136, "synWp": 122, "synEv": 17, "synAll": -5, "balkon": 84, "alles": 5572}, "guen_heute": {"hh": 0.3695, "wpVar": 1505, "wpFix": 163, "evVar": 1890, "evFix": 67, "pv": 582, "synWp": 276, "synEv": 167, "synAll": -5, "balkon": 202, "alles": 4644}, "guen_reform": {"hh": 0.2311, "wpVar": 3013, "wpFix": 123, "evVar": 3104, "evFix": 342, "pv": 439, "synWp": 79, "synEv": 11, "synAll": 2, "balkon": 87, "alles": 7113}};\nconst E_BASIS = { waerme: 15000, km: 13500, kwp: 10 };\n// Aus verknüpften Rechnern übernommen: je Rechner { heute, reform }; ersetzt die Schätzung der Maßnahmen, die dieser Rechner abdeckt\nconst E_DECKT = { "Heizungsrechner": ["wp"], "E-Auto-Rechner": ["ev"], "Energie-Rechner": ["pv"], "Balkon-Rechner": ["balkon"] };   // der Energie-Rechner gibt nur zurück, was die Solaranlage bringt\nconst E_EXTERN = {};\nlet E_STROM_EIGEN = false;   // Haushaltsstrom selbst eingetragen? Sonst nach Personen geschätzt\nconst eUebernimm = (quelle, h, r) => { quelle = String(quelle || "").slice(0, 40); if (!E_DECKT[quelle]) return; E_EXTERN[quelle] = { heute: +h || 0, reform: +r || 0 }; };\ntry { const q = new URLSearchParams(location.search); if (q.has("eHeute") && q.has("eReform")) eUebernimm(q.get("eQuelle"), q.get("eHeute"), q.get("eReform")); } catch (e) {}\naddEventListener("message", ev => { if (ev.origin !== location.origin || !ev.data || ev.data.typ !== "energie-ersparnis") return; eUebernimm(ev.data.quelle, ev.data.heute, ev.data.reform); $("energieBox").open = true; updateHH(); });\nfunction energieLesen() {\n  const n = id => Math.max(0, parseFloat($(id).value) || 0);\n  const pers = (+$("erw").value || 1) + (Math.round(parseFloat($("kinder").value) || 0)), stromAuto = [0, 1500, 2500, 3500][Math.min(3, pers)] || 4000;\n  if (!E_STROM_EIGEN) $("e_strom").value = stromAuto;\n  return { fall: $("e_fall").value, strom: n("e_strom"), wp: $("e_wp").value === "1", waerme: n("e_waerme"), ev: $("e_ev").value === "1", km: n("e_km"), kwp: Math.min(30, n("e_pv")), balkon: $("e_balkon").checked, hhstrom: $("e_hhstrom").checked };\n}\nfunction energieRechne(e) {\n  const out = {};\n  for (const r of ["heute", "reform"]) {\n    const k = ENERGIE[e.fall + "_" + r], t = [], ext = new Set(Object.keys(E_EXTERN).flatMap(q => E_DECKT[q]));\n    for (const [q, x] of Object.entries(E_EXTERN)) t.push([`Aus dem ${q}${q === "Energie-Rechner" ? " (Solaranlage)" : ""}`, x[r]]);\n    if (e.wp && !ext.has("wp")) t.push(["Wärmepumpe statt Gasheizung (geschätzt)", k.wpVar * e.waerme / E_BASIS.waerme + k.wpFix]);\n    if (e.ev && !ext.has("ev")) t.push(["E-Auto statt Verbrenner (geschätzt)", k.evVar * e.km / E_BASIS.km + k.evFix]);\n    const pvF = Math.min(e.kwp / E_BASIS.kwp, 1.5);\n    if (e.kwp > 0 && !ext.has("pv")) t.push([`Solaranlage ${fmt(e.kwp, 1)} kWp (geschätzt)`, k.pv * pvF + (e.wp ? k.synWp * pvF : 0) + (e.ev ? k.synEv * pvF : 0) + (e.wp && e.ev ? k.synAll * pvF : 0)]);\n    if (e.balkon && !ext.has("balkon")) t.push(["Balkonkraftwerk 800 W (geschätzt)", k.balkon]);\n    out[r] = { teile: t, summe: t.reduce((s, x) => s + x[1], 0), preis: k.hh };\n  }\n  out.hhstrom = e.hhstrom ? e.strom * (out.heute.preis - out.reform.preis) : 0;\n  return out;\n}\nfunction energieLinks(e) {\n  const q = o => new URLSearchParams(o).toString();\n  const l = [];\n  if (e.wp) l.push(`<a href="../heizungsrechner/?${q({ waerme: e.waerme })}" target="_blank" rel="opener">Heizungsrechner</a>`);\n  if (e.ev) l.push(`<a href="../eauto-rechner/?${q({ km: e.km })}" target="_blank" rel="opener">E-Auto-Rechner</a>`);\n  if (e.kwp > 0 || (e.wp && e.ev)) l.push(`<a href="../energie-rechner/?${q({ hh: e.strom, pvS: e.kwp, waerme: e.waerme, km: e.km, wpAn: e.wp ? "ja" : "nein", evAn: e.ev ? "ja" : "nein" })}" target="_blank" rel="opener">Energie-Rechner</a>`);\n  if (e.balkon) l.push(`<a href="../balkon-rechner/?${q({ hh: e.strom })}" target="_blank" rel="opener">Balkon-Rechner</a>`);\n  return l.length ? `Genau rechnen, mit deinen Werten: ${l.join(" · ")}. Die Rechner öffnen sich in einem neuen Fenster.` : "Wähl oben, was du ändern willst. Dann erscheinen die Links zu den Rechnern, die es genau rechnen.";\n}\nfunction energieZeigen(plus) {\n  const e = energieLesen(), E = energieRechne(e), box = $("energieErg");\n  $("e_links").innerHTML = energieLinks(e);\n  const qs = Object.keys(E_EXTERN);\n  $("e_quelle").innerHTML = qs.length ? `<p class="note"><b>Übernommen aus ${qs.map(q => "dem " + esc(q)).join(" und ")}.</b> Für diese Maßnahmen gilt die genaue Rechnung statt der Schätzung. <button type="button" class="leise" id="e_reset">Wieder schätzen</button></p>` : "";\n  if (qs.length) $("e_reset").onclick = () => { qs.forEach(q => delete E_EXTERN[q]); updateHH(); };\n  const H = E.heute.summe, R = E.reform.summe + E.hhstrom;\n  if (Math.abs(H) < 0.5 && Math.abs(R) < 0.5) { box.hidden = true; return { heute: 0, reform: 0 }; }\n  box.hidden = false;\n  const zeile = (n, h, r) => `<tr><td>${n}</td><td>${sign(h)} €</td><td>${sign(r)} €</td></tr>`;\n  const namen = [...new Set([...E.heute.teile, ...E.reform.teile].map(x => x[0]))];\n  const wert = (teile, n) => (teile.find(x => x[0] === n) || [0, 0])[1];\n  const gesamt = plus + R - H;\n  box.innerHTML = `<h3>Mit Energie und Auto: ${eur(Math.abs(gesamt) / 12)} im Monat ${gesamt >= 0 ? "mehr" : "weniger"} als heute</h3>\n    <p class="note">Energie und Auto bringen heute ${eur(H)} im Jahr, mit der Reform ${eur(R)}. Zusammen mit dem Ergebnis oben ${gesamt >= 0 ? "bleiben" : "fehlen"} ${eur(Math.abs(gesamt))} im Jahr gegenüber heute.</p>\n    <div class="tbl-wrap"><table><thead><tr><th>Ersparnis im Jahr</th><th>Heute</th><th>Reform</th></tr></thead><tbody>\n    ${namen.map(n => zeile(n, wert(E.heute.teile, n), wert(E.reform.teile, n))).join("")}\n    ${E.hhstrom ? zeile(`Strom mit 5 % Mehrwertsteuer, ohne Umlagen: ${fmt(e.strom)} kWh Haushaltsstrom`, 0, E.hhstrom) : ""}\n    <tr class="sum"><td>Zusammen</td><td>${sign(H)} €</td><td>${sign(R)} €</td></tr></tbody></table></div>\n    <p class="note">Entwurf, grobe Schätzung: ${({ ung: "ungünstige", wahr: "wahrscheinliche", guen: "günstige" })[e.fall]} Annahmen. Gezählt wird, was die Anlagen sparen, und der billigere Strom, wenn eingeschaltet. Die Schätzung lädt und heizt im günstigsten Stromtarif (heute dynamisch, mit der Reform mit den 8 Stunden ohne Netzentgelt); der E-Auto- und der Heizungsrechner rechnen mit dem Strompreis, den du dort einträgst, und liegen deshalb etwas darunter. Die höhere Mehrwertsteuer auf Gas und Benzin steckt schon in der Rechnung oben, das Klimageld ist nicht eingerechnet.</p>`;\n  return { heute: H, reform: R };\n}\n$("e_strom").addEventListener("input", () => { E_STROM_EIGEN = $("e_strom").value !== ""; });\n$("energieBox").addEventListener("input", ev => { ev.stopPropagation(); updateHH(); });\n$("energieBox").addEventListener("change", ev => { ev.stopPropagation(); updateHH(); });\nif (Object.keys(E_EXTERN).length) $("energieBox").open = true;\n\n'
def vor(s, anker, neu):
    assert s.count(anker) == 1, "Anker nicht eindeutig: " + anker[:60]
    return s.replace(anker, neu + anker, 1)
s = vor(s, '        <p class="note">Alle Beträge in Euro, Rechtsstand 2026.', BOX)
s = vor(s, '        <div class="teilen" id="teilen"', ERG)
s = vor(s, "function updateHH() {", JS)
s = vor(s, "  teilenUpdate(r.vgl + r.entfall);", "  const eErg = energieZeigen(plus);\n")
open(P, "w", encoding="utf-8").write(s)
print("Kasten Energie und Auto eingebaut:", P)
